package ec.edu.unl.sec.selfassessment.domain;import static org.assertj.core.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;class FixedModelSnapshotTest{@Test void activationFixesExactModelAndIndicators(){UUID model=UUID.randomUUID(),indicator=UUID.randomUUID();var p=new SelfAssessmentProcess(null,UUID.randomUUID(),"P-1","Proceso",LocalDate.now(),LocalDate.now().plusDays(1),model,1,ProcessState.DRAFT,0,UUID.randomUUID(),Instant.now(),List.of());var active=p.activate(List.of(new SelfAssessmentProcess.IndicatorSnapshot(indicator,"I-1","Indicador")));assertThat(active.modelVersionId()).isEqualTo(model);assertThat(active.modelVersionNumber()).isEqualTo(1);assertThat(active.indicators()).extracting(SelfAssessmentProcess.IndicatorSnapshot::id).containsExactly(indicator);}}
